function resolveConflict(writeA, writeB) {
  if (writeA.timestamp >= writeB.timestamp) {
    return writeA;
  }
  return writeB;
}
// writeA and writeB carry a region-tagged, clock-synchronized timestamp
// the loser is discarded entirely, its update is gone

